// models/SponsorshipRequest.js
const mongoose = require('mongoose');

/**
 * SponsorshipRequest Schema
 * Maps to the SponsorshipRequest Class: requestID, zkpToken, amountNeeded, academicPurpose, status[cite: 1].
 */
const SponsorshipRequestSchema = new mongoose.Schema({
  requestID: {
    type: String,
    required: true,
    unique: true,
    // Typically auto-generated (e.g., UUID or custom prefix like REQ-ZKP-123)
  },
  zkpToken: {
    type: String,
    required: true,
    // Stores the Base64 encoded token generated by the Privacy Module[cite: 1]
  },
  amountNeeded: {
    type: Number,
    required: true,
    min: [1, 'Amount needed must be greater than zero']
  },
  academicPurpose: {
    type: String,
    required: true,
    // Defines the deficit category such as Tuition or Accommodation[cite: 1]
  },
  status: {
    type: String,
    enum: ['Pending', 'Funded', 'Verified', 'Closed'],
    default: 'Pending'
  },
  // Internal reference strictly for fund routing and wallet updates after a successful transaction[cite: 1].
  // This is kept strictly on the backend and never exposed to the sponsor feed API.
  studentRef: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true,
    select: false // Prevents Mongoose from returning this field by default to maintain anonymity
  }
}, { timestamps: true });

const SponsorshipRequest = mongoose.model('SponsorshipRequest', SponsorshipRequestSchema);

module.exports = SponsorshipRequest;